arguments.cmd:
cd /tmp && python3 - <<'EOF'
import struct, subprocess
def run(bn, sz, datalen):
    data = struct.pack('<ii', bn, sz) + b'A'*datalen
    open('t.bin','wb').write(data)
    p = subprocess.run(['/workspace/artifacts/target/s7dl','t.bin'], capture_output=True, text=True, timeout=10)
    return p.returncode, p.stdout.strip().replace('\n',' | ')

cases = [
    (0, -1, 0), (0, -100, 0), (0, 0x7fffffff, 0), (0, 65536, 65536),
    (0, 8192, 8192), (0, 100000, 100000), (0, 1000000, 1000),
    (1, 512, 512), (-1, 512, 512), (0x7fffffff, 512, 512),
    (0, 16, 0), (0, 16, 8), (0, 8, 16), (0, 4096, 0),
]
for bn, sz, dl in cases:
    try:
        rc, out = run(bn, sz, dl)
    except Exception as e:
        rc, out = 'EXC', str(e)
    print(f"bn={bn} sz={sz} dl={dl} rc={rc} -> {out[:120]}")
EOF

